import { useEffect, useState } from "react";
import Card from "../components/Card";
import Loader from "../components/Loader";
import DashboardLayout from "../layouts/DashboardLayout";
import api from "../services/api";

export default function Dashboard() {
  const [summary, setSummary] = useState(null);

  useEffect(() => {
    Promise.all([
      api.get("/campaigns"),
      api.get("/donations"),
      api.get("/volunteers")
    ]).then(([campaignsRes, donationsRes, volunteersRes]) => {
      const totalDonations = donationsRes.data.reduce((sum, donation) => sum + Number(donation.amount || 0), 0);
      setSummary({
        campaigns: campaignsRes.data.length,
        donations: donationsRes.data.length,
        volunteers: volunteersRes.data.length,
        totalDonations
      });
    }).catch(() => {
      setSummary({ campaigns: 0, donations: 0, volunteers: 0, totalDonations: 0 });
    });
  }, []);

  return (
    <DashboardLayout title="Dashboard">
      {!summary ? (
        <Loader />
      ) : (
        <div className="grid">
          <Card title="Campaigns" value={summary.campaigns} />
          <Card title="Donations" value={summary.donations} />
          <Card title="Volunteers" value={summary.volunteers} />
          <Card title="Total Raised" value={`Rs ${summary.totalDonations.toLocaleString("en-IN")}`} />
        </div>
      )}
    </DashboardLayout>
  );
}
